<?php
session_start();include '../includes/session_manager.php';if(empty($_SESSION['logged_in'])||($_SESSION['role']??'')!=='Student'){header('Location: ../student_login.php');exit();}
include '../includes/db_connect.php';require_once '../includes/benefit_releases.php';
$stmt=$pdo->prepare("SELECT a.ApplicationID,a.Status,s.Name AS ScholarshipName,s.AwardAmount,COALESCE(ba.TotalEntitlement,s.AwardAmount,0) AS TotalEntitlement,COALESCE(ba.ReleaseFrequency,s.ReleaseFrequency,'Per Semester') AS ReleaseFrequency,COALESCE((SELECT SUM(br.Amount) FROM benefit_releases br WHERE br.ApplicationID=a.ApplicationID),0) AS ReleasedAmount FROM application a JOIN scholarship s ON s.ScholarshipID=a.ScholarshipID LEFT JOIN scholar_benefit_accounts ba ON ba.ApplicationID=a.ApplicationID WHERE a.UserID=? AND (a.Status='Approved' OR ba.BenefitAccountID IS NOT NULL) ORDER BY a.DateSubmitted DESC");$stmt->execute([$_SESSION['user_id']]);$accounts=$stmt->fetchAll(PDO::FETCH_ASSOC);$releases=[];if($accounts){$ids=array_map('intval',array_column($accounts,'ApplicationID'));$rs=$pdo->query("SELECT * FROM benefit_releases WHERE ApplicationID IN (".implode(',',$ids).") ORDER BY PaymentDate DESC,BenefitReleaseID DESC");foreach($rs->fetchAll(PDO::FETCH_ASSOC)as$r)$releases[(int)$r['ApplicationID']][]=$r;}
include '../includes/header.php';include '../includes/student_sidebar.php';
?>
<main class="flex-1 p-5 lg:p-10 lg:ml-72 bg-slate-50/50 min-h-screen"><header class="mb-8"><h2 class="text-3xl lg:text-4xl font-black text-slate-900">My Scholarship Benefits</h2><p class="text-slate-500 mt-2">View actual payments, acknowledgement receipts, and unpaid balances.</p></header><?php if(!$accounts):?><div class="bg-white border border-slate-200 rounded-[2rem] p-12 text-center"><div class="text-4xl mb-4">💳</div><h3 class="text-xl font-black">No active benefit account</h3><p class="text-slate-500 mt-2">Benefit records will appear after your scholarship is approved.</p></div><?php endif;?><div class="space-y-6"><?php foreach($accounts as$a):$total=(float)$a['TotalEntitlement'];$paid=(float)$a['ReleasedAmount'];$balance=max(0,$total-$paid);?><section class="bg-white border border-slate-200 rounded-[2rem] p-6 lg:p-8"><div class="flex flex-col md:flex-row justify-between gap-4"><div><p class="text-xs font-black text-blue-600 uppercase tracking-widest"><?=htmlspecialchars($a['ReleaseFrequency'])?></p><h3 class="text-xl font-black text-slate-900 mt-1"><?=htmlspecialchars($a['ScholarshipName'])?></h3></div><div class="grid grid-cols-3 gap-5 text-right"><div><p class="text-[9px] font-black text-slate-400 uppercase">Entitlement</p><p class="font-black">₱<?=number_format($total,2)?></p></div><div><p class="text-[9px] font-black text-slate-400 uppercase">Received</p><p class="font-black text-green-600">₱<?=number_format($paid,2)?></p></div><div><p class="text-[9px] font-black text-slate-400 uppercase">Unpaid</p><p class="font-black text-amber-600">₱<?=number_format($balance,2)?></p></div></div></div><div class="mt-6 space-y-3"><?php if(empty($releases[(int)$a['ApplicationID']])):?><p class="p-5 border border-dashed rounded-2xl text-center text-sm text-slate-400">No payment has been released yet.</p><?php endif;?><?php foreach($releases[(int)$a['ApplicationID']]??[]as$r):?><div class="p-4 bg-slate-50 border border-slate-200 rounded-2xl flex flex-col sm:flex-row justify-between gap-3"><div><p class="font-black text-green-700">₱<?=number_format($r['Amount'],2)?></p><p class="text-xs font-bold text-slate-500 mt-1"><?=htmlspecialchars($r['ReleasePeriod'])?> · <?=htmlspecialchars($r['ReleaseMode'])?><?= $r['ReferenceNumber']?' · Ref '.htmlspecialchars($r['ReferenceNumber']):''?></p></div><div class="sm:text-right"><p class="text-xs font-black text-slate-600"><?=date('M d, Y',strtotime($r['PaymentDate']))?></p><a target="_blank" href="<?=htmlspecialchars(benefitReceiptUrl($r['AcknowledgementReceipt']))?>" class="inline-block mt-2 text-xs font-black text-blue-600">View Acknowledgement Receipt</a></div></div><?php endforeach;?></div></section><?php endforeach;?></div></main>
<?php include '../includes/footer.php';?>
